Given a non-negative integer n, the task is to find the nth row of Pascal's Triangle. Note: The row index starts from 1.Examples:Input: n = 4Output: 1 3 3 1Explanation: The elements in the 4th row are 1 3 3 1 as shown in Pascal Triangle. Input: n = 1Output: 1Explanation: The elements in the 1th row is 1 as shown in Pascal Triangle.Try It YourselfTable of Content[Naive Approach] Using Recursion - O(2^n) Time and O(n) Space[Better Approach] Using Recursion Level by Level - O(n^2) Time and O(n) Space[Expected Approach] Using Combinatorics - O(n) Time and O(n) Space[Naive Approach] Using Recursion - O(2^n) Time and O(n) SpaceThe idea is to use the property that each element i in the Pascal triangle is equal to the sum of two elements directly above it (i-1 and i), with the base condition that the first and last element of any row will be equal to 1.
            C++

    // C++ program to Find the nth row in 
// Pascal’s Triangle using Recursion 
#include <bits/stdc++.h>
using namespace std;

// Function which recursively finds the 
// ith value of nth row.
int findVal(int i, int n) {

    // First and last value of each 
    // row will always be 1.
    if (i == 1 || i == n) {
        return 1;
    }

    // Find the (i-1)th and ith 
    // value of previous row 
    return findVal(i-1, n-1) + findVal(i, n-1);
}

// Function to find the elements 
// of n'th row in Pascal's Triangle 
vector<int> nthRowOfPascalTriangle(int n) { 
    vector<int> res;

    for (int i=1; i<=n; i++) {
        int val = findVal(i, n);
        res.push_back(val);
    }

    return res;
} 

int main() {

    int n = 4; 
    vector<int> ans = nthRowOfPascalTriangle(n); 

    for(int i = 0; i < ans.size(); i++) {
        cout << ans[i] << " ";
    } 
    cout << endl;
    return 0;
}


